

create table if not EXISTS segmentation_geo (
   id_region int,
   nom_region varchar(20),
   pays varchar(20),
   primary key (id_region)
  );


select * from segmentation_geo;


create table if not EXISTS segmentation_produit (
    departement varchar(100),
    branche varchar(100),
    primary key (departement)
  );




select * from segmentation_produit ;



create table if NOT EXISTS  employes
  (
      id integer,
      nom varchar(100),
      email varchar(200),
      sexe varchar(10),
      departement varchar(100),
      date_debut date,
      salaire float,
      job_title varchar(100),
      id_region int,
      primary key (id)
  );


select * from segmentation_geo ;
select * from segmentation_produit;
select * from employes;
select count(*) from employes ;

create view alpha as select * from employes ;
select * from alpha ;

select 
s.nom,
s.salaire,
s.departement,
(select avg (ss.salaire) from employes ss where s.departement = ss.departement) as Moyen
from employes s
;
select 
ss.nom,
ss.departement,
ss.salaire
from employes ss
where ss.salaire = (select max (s.salaire) from employes s );
